import type { AxisKey, ReferenceEntry } from './references';

const axisKeys: readonly AxisKey[] = ['est','rep','pod','imi','dip','int','eco','con','com','rel','mor','tec'];
type AxisEvidenceSeed = { score: number; reason: string };
type EuropeSeed = {
  id: string; name: string; category: 'public-figure' | 'historical-figure'; period: string;
  title: string; url: string; note: string; rationale: string; caveats: string;
  axes: Partial<Record<AxisKey, AxisEvidenceSeed>>;
};

const makeEntry = (p: EuropeSeed): ReferenceEntry => {
  const source = { title: p.title, url: p.url, note: p.note };
  const axes = Object.entries(p.axes) as [AxisKey, AxisEvidenceSeed][];
  return {
    id: p.id, kind: 'person', category: p.category, name: p.name, period: p.period,
    vec: Object.fromEntries(axisKeys.map((key) => [key, p.axes[key]?.score ?? 50])) as Record<AxisKey, number>,
    rationale: p.rationale, caveats: p.caveats, sources: [source],
    evidence: Object.fromEntries(axes.map(([key]) => [key, 'medium'])),
    axisEvidence: Object.fromEntries(axes.map(([key, item]) => [key, { sourceTitles: [p.title], rationale: item.reason }])),
  };
};

